/// <summary>
/// AVA/WEN/2025/06/18      AVA_012442_PostedProjectHors.
/// </summary>
/// <param name = "_query">Query</param>
public void initializeQuery(Query _query)
{
    next initializeQuery(_query);

    queryBuildDataSource = _query.dataSourceTable(tableNum(ProjPostTransView));
    QueryBuildRange transDateRange = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(ProjPostTransView, TransDate));
    transDateRange.value(SysQueryRangeUtil::dateRange(DateTimeUtil::date(DateTimeUtil::minValue()), DateTimeUtil::date(DateTimeUtil::maxValue())));

    FormDateControl dateControl = this.listPage().formRun().design().controlName(formControlStr(projProjectTransactionsListPage, TransStartDate));
    if (dateControl)
    {
        dateControl.dateValue(dateNull());
    }

    this.linkActive(_query);
}
